Let $\mathsf{G}\subseteq \mathsf{O}(d)$ be any compact subgroup. Fix any $\theta_* \in \mathbb{R}^d$ and any integer $K \geq 0$.

(a) In the unprojected orbit recovery model, $R(\theta)$ admits an expansion $$R(\theta)=C_0+\sum_{k=1}^K \frac{1}{\sigma^{2k}}\,
    \Big(s_k(\theta)+q_k(\theta)\Big)+q(\theta).\tag{2.7}$$ Here $C_0 \in \mathbb{R}$, $q_k \in \mathcal{R}_{\leq k-1}^\mathsf{G}$ is a polynomial of degree at most $2k$, and $s_k \in \mathcal{R}_{\leq k}^\mathsf{G}$ is the polynomial $$s_k(\theta)=\frac{1}{2(k!)}\|T_k(\theta)-T_k(\theta_*)\|_{\mathrm{HS}}^2.\tag{2.8}$$ The remainder $q(\theta)$ is $\mathsf{G}$-invariant and satisfies, for all $\theta \in \mathbb{R}^d$ with $\|\theta\| \leq \sigma$, $$|q(\theta)| \leq \frac{C_K(1 \vee \|\theta\|)^{2K+2}}{\sigma^{2K+2}},\;\;
    \|\nabla q(\theta)\| \leq \frac{C_K(1 \vee\|\theta\|)^{2K+1}}
    {\sigma^{2K+2}},\;\;
    \|\nabla^2 q(\theta)\| \leq \frac{C_K(1 \vee\|\theta\|)^{2K}}
    {\sigma^{2K+2}}.\tag{2.9}$$

(b) In the projected orbit recovery model, $R(\theta)$ admits an expansion $$R(\theta)=C_0+\sum_{k=1}^K \frac{1}{\sigma^{2k}}\,
    \Big(\tilde{s}_k(\theta)+\big\langle {\widetilde{T}}_k(\theta),P_k(\theta)\big\rangle
    +q_k(\theta)\Big)+q(\theta).\tag{2.10}$$ Here $C_0 \in \mathbb{R}$, $q_k \in \mathcal{\widetilde{R}}_{\leq k-1}^\mathsf{G}$ is a polynomial of degree at most $2k$, all entries of $P_k$ are polynomials of degree at most $k$ belonging to $\mathcal{\widetilde{R}}_{\leq k-1}^\mathsf{G}$, $P_k$ satisfies $P_k(\theta_*)=0$ and $\tilde{s}_k \in \mathcal{\widetilde{R}}_{\leq k}^\mathsf{G}$ is the polynomial $$\tilde{s}_k(\theta)=\frac{1}{2(k!)}\|{\widetilde{T}}_k(\theta)-{\widetilde{T}}_k(\theta_*)\|_{\mathrm{HS}}^2.\tag{2.11}$$ The remainder $q(\theta)$ is $\mathsf{G}$-invariant and satisfies (2.9) for all $\theta \in \mathbb{R}^d$ with $\|\theta\| \leq \sigma$.

The above constants $C_0,C_K$, the coefficients of the polynomials $q_k(\theta)$ and $P_k(\theta)$, and the forms of the functions $q(\theta)$ may all depend on $\theta_*,\mathsf{G},d,\tilde{d}$ and the projection $\Pi$.

For any $L \geq 1$ and $S_0,\ldots,S_L \geq 1$, $$\begin{aligned}
s_1(\theta)&=\frac{1}{2}\sum_{s=1}^{S_0} \Big(u^{(0s)}(\theta)-
u^{(0s)}(\theta_*)\Big)^2,\\
s_2(\theta)&=\frac{1}{4}\sum_{l=0}^L \frac{1}{2l+1}
\sum_{s,s'=1}^{S_l} \Big(\langle u^{(ls)}(\theta),u^{(ls')}(\theta) \rangle
-\langle u^{(ls)}(\theta_*),u^{(ls')}(\theta_*) \rangle\Big)^2,\\
s_3(\theta)&=\frac{1}{12}\mathop{\sum_{l,l',l''=0}^L}_{|l-l'| \leq l'' \leq
l+l'} \frac{1}{2l''+1}\sum_{s=1}^{S_l}\sum_{s'=1}^{S_{l'}}\sum_{s''=1}^{S_{l''}}
\Big(B_{(l,s),(l',s'),(l'',s'')}(\theta)-B_{(l,s),(l',s'),(l'',s'')}(\theta_*)\Big)^2.
\end{aligned}$$

Let $[a,b]\subseteq[0,\pi],a\leq b$. Assume that Assumption 3.1–3.5 hold, and consider a mapping $\mathscr G_\Upsilon$ of the form (3.23) that satisfies Assumption 3.6 for some $x\geq1$.

(a) case $\phi(z)=z$: Assume the above conditions with $p\geq6$. Then
\[
\left\{\rho_T M^{1/2}\left(\big(L_{U_M}^{a,b}\circ\mathscr G_\Upsilon(\widehat{\mathscr F})\big)(\eta)-\big(L^{a,b}\circ\mathscr G_\Upsilon(\mathscr F)\big)(\eta)\right)\right\}_{\eta\in I}
\overset{\mathscr D}{\Longrightarrow}\left\{\eta^{x-1}\mathbb W_{\mu_\Upsilon}(\eta)\right\}_{\eta\in I},\tag{3.27}
\]
where $\mathbb W_{\mu_\Upsilon}$ denotes a Brownian motion on $S_1(\mathcal H)$ corresponding to a zero-mean Gaussian measure $\mu_\Upsilon$ with covariance operator $\tau_\Upsilon^2=\int_0^1\Gamma_\Upsilon^{(u)}du$, pseudo-covariance operator $\widetilde\tau_\Upsilon^2=\int_0^1\Sigma_\Upsilon^{(u)}du$, and where $\Gamma_\Upsilon^{(u)}$ and $\Sigma_\Upsilon^{(u)}\in S_1(\mathcal H\otimes\mathcal H)$ are defined in (B.11) and (B.12), respectively.

(b) case $\phi(z)\neq z$: assume the above conditions with $p$ such that (3.30) holds. In addition, assume that $\mathscr F\in\mathbb D_1$ and that for some $0<\rho<1$,
\[
\sum_{r\in\mathbb N}\sum_{j=l}^\infty\nu_{\mathbb C,p}^{X_\cdot^\cdot(e_r)}(j)=O((l+1)^{-\rho}).\tag{3.28}
\]
Then for analytic functions $\phi(z)$ that satisfy $\phi'(cz)=h(c)\phi'(z)$, where $c\in[0,1]$ and $h$ is a continuous function with $h(1)=1$,
\[
\left\{\rho_T M^{1/2}\left(\big(L_{U_M}^{a,b}\circ\mathscr G_\Upsilon(\widehat{\mathscr F})\big)(\eta)-\big(L^{a,b}\circ\mathscr G_\Upsilon(\mathscr F)\big)(\eta)\right)\right\}_{\eta\in I}
\overset{\mathscr D}{\Longrightarrow}\left\{\eta^{x-1}h(\eta)\mathbb W_{\mu_\Upsilon}(\eta)\right\}_{\eta\in I}.\tag{3.29}
\]

Suppose the conditions of Theorem 3.1(b) hold true and that $\lambda_1^{(u,\omega)}>\ldots>\lambda_d^{(u,\omega)}>0$ uniformly in $(u,\omega)\in[0,1]\times[0,\pi]$. Then
\[
\left\{M^{1/2}\rho_T\eta^3\left(\frac{\sum_{i=1}^d\frac1M\sum_{u\in U_M}\int_a^b\widehat\lambda_i^{(u,\omega)}(\eta)d\omega}{\frac1M\sum_{u\in U_M}\int_a^b\operatorname{Tr}\big(\widehat{\mathscr F}_{u,\omega}(\eta)\big)d\omega}-\frac{\sum_{i=1}^d\int_0^1\int_a^b(\lambda_i^{(u,\omega)})d\omega du}{\int_0^1\int_a^b\operatorname{Tr}\big(\mathscr F_{u,\omega}\big)d\omega du}\right)\right\}_{\eta\in I}
\overset{\mathscr D}{\Longrightarrow}\left\{\eta^2\sigma\mathbb B(\eta)\right\}_{\eta\in I}\tag{3.42}
\]
for some $\sigma\geq0$ and a standard Brownian motion $\mathbb B$.

Suppose the conditions of Theorem 3.1(b) hold true and that $\delta_1^{(u,\omega)}>\ldots>\delta_d^{(u,\omega)}>0$ uniformly in $(u,\omega)\in[0,1]\times[0,\pi]$. Then
\[
\left\{M^{1/2}\rho_T\eta^3\left(\frac{\sum_{j=1}^d\frac1M\sum_{u\in U_M}\int_a^b(\widehat\delta_j^{(u,\omega)}(\eta))^2d\omega}{\sum_{j=1}^\infty\frac1M\sum_{u\in U_M}\int_a^b(\widehat\delta_j^{(u,\omega)}(\eta))^2d\omega}-\frac{\sum_{j=1}^d\int_0^1\int_a^b(\delta_j^{(u,\omega)})^2d\omega du}{\sum_{j=1}^\infty\int_0^1\int_a^b(\delta_j^{(u,\omega)})^2d\omega du}\right)\right\}_{\eta\in I}
\overset{\mathscr D}{\Longrightarrow}\left\{\eta^2\sigma\mathbb B(\eta)\right\}_{\eta\in I}\tag{3.44}
\]
for some $\sigma\geq0$ and a standard Brownian motion $\mathbb B$.

Suppose the conditions of Theorem 3.1(b) hold true and that $\nu_1^{u,\omega}>\ldots>\nu_d^{u,\omega}>0$ and $\lambda_{ii,1}^{(u,\omega)}>\ldots,\lambda_{ii,d}^{(u,\omega)}>0$, $i\in\{1,2\}$. Then,
\[
\left\{M^{1/2}\rho_T\left(\frac1M\sum_{u\in U_M}\int_a^b\eta^4\widehat{\mathscr R}_d^{u,\omega}(\eta)d\omega-\int_0^1\int_a^b\eta^4\mathscr R_d^{u,\omega}d\omega du\right)\right\}_{\eta\in I}
\overset{\mathscr D}{\Longrightarrow}\left\{\eta^3\sigma\mathbb B(\eta)\right\}_{\eta\in I}\tag{3.45}
\]
for some $\sigma\geq0$ and a standard Brownian motion $\mathbb B$.

If Assumptions (A1), (A2), (A3) are satisfied, $\log d=o(n^\gamma)$ with $0\leq\gamma\leq\frac1{2/\beta+1}$ and
\[
\frac{B_n^2\big(\log(nd)\big)^{4+2/\beta}}n=o(1),\quad n\to\infty,\tag{2.16}
\]
then, for any $\alpha\in(0,1-e^{-1})$,
\[
\limsup_{n\to\infty}\sup_{F\in\mathcal H_0(\Delta)}
\mathbb P\left(\mathcal T_{n,\Delta}>\frac{q_{1-\alpha}}{a_d}+b_d\right)\leq\alpha,\tag{2.17}
\]
with strict inequality, whenever $\limsup_{n\to\infty}|\{i\in\{1,\ldots,d\}:|\theta_i|=\Delta\}|/d<1$. Moreover,
\[
\lim_{n\to\infty}\sup_{F\in\mathcal H_0(\Delta)}
\mathbb P\left(\mathcal T_{n,\Delta}>\frac{q_{1-\alpha}}{a_d}+b_d\right)
=\begin{cases}
\alpha,&\text{if }|\theta_i|=\Delta\text{ for all }1\leq i\leq d,\\
0,&\text{if }\sup_{d\in\mathbb N}\max_{i=1}^d|\theta_i|<\Delta.
\end{cases}
\]

Assume that the dependence measure $d_{ij}$ in (2.4) is given by $d_{ij}=\operatorname{Cov}_F(X_{1i},X_{1j})$ and $d_{ii}=1$ $(i,j=1,\ldots,p)$; so we have $d=p(p-1)/2$. Further let $c_0,\alpha,\beta$ denote positive constants such that $c_0<1-\Delta$ and $\alpha+\beta<1$. If $\log(p)/n\to0$ and $\log(p)n/p^2\to0$, as $n\to\infty$, then we have for sufficiently large $n$ and $p$
\[
\inf_{T_\alpha\in\mathcal T_\alpha}\sup_{F\in\mathcal H_1(c_0)}
\mathbb P(T_\alpha\text{ does not reject }H_0)\geq1-\alpha-\beta.\tag{3.3}
\]

Suppose $\mathcal U_n$ is such that there exists $A_n>0$ and $\rho_n\in\mathbb R$ so that (21) holds with $\liminf_n\rho_n>0$, $\rho_n\log A_n=o(n)$, and $\liminf_n\rho_n\log A_n>0$. Further suppose there exist $(\widetilde f_{n,1},\widetilde f_{n,2})\in\mathcal U_n$ so that
\[
\|\widetilde f_{n,1}/a_n-(\eta_1-1/2)\|_\infty+\|\widetilde f_{n,2}/a_n-(\eta_2-1/2)\|_\infty\leq\left(\frac{\rho_n\log A_n}{n}\right)^{1/(2+\alpha)}\tag{22}
