Fix $d,n\in\mathbb N$, $\mathcal O\subseteq\{0,1\}^d$, $o_1,\ldots,o_n\in\mathcal O$, $\Omega_\star\in\mathcal I(\{0,1\}^d)\setminus\{\{\mathbf0_d\},\emptyset\}$, $c_{\mathrm E}\in(0,1/4]$, $\boldsymbol\gamma\in[0,\infty)^d$, $C_{\mathrm L}\ge1$, $\boldsymbol\beta\in(0,1]^d$, $C_{\mathrm S}\ge1$, $\alpha\in[0,\infty)$ and $C_{\mathrm M}\ge1$. Suppose that $\Omega_\star\subseteq\mathcal N$ and we have $\min_{\omega\in\Omega_\star}\gamma_\omega>\max_{\omega\in\Omega_\star}\beta_\omega/d_\omega$. Suppose that $n_\omega\ge\log^{\frac{4(\gamma_\omega(2\beta_\omega+d_\omega)+\alpha\beta_\omega)}{\beta_\omega\gamma_\omega}}\big(2|\mathcal N|\min_{\omega'\in\Omega_\star}n_{\omega'}\big)$, for $\omega\in U(\Omega_\star)\cap\mathcal N$, then there exists a constant $C_{\mathrm U}\ge1$ (not depending on $n$ nor $o_1,\ldots,o_n$) such that
\[
\sup_{Q\in\mathcal Q^+_{\mathrm{Miss}}}\mathbb E_Q\left\{\mathcal E_{P_Q}(\widehat C_{\mathrm{HAM}})\mid O_1=o_1,\ldots,O_n=o_n\right\}
\le C_{\mathrm U}\cdot\log_+^{\frac{1+\alpha}2}\left(\min_{\omega\in\Omega_\star}n_\omega\right)\cdot\max_{\omega\in\Omega_\star}\left\{n_\omega^{-\frac{\beta_\omega\gamma_\omega(1+\alpha)}{\gamma_\omega(2\beta_\omega+d_\omega)+\alpha\beta_\omega}}\right\}.\tag{14}
\]

Let $f_1,\ldots,f_\kappa$ be functions on $\mathbb R$ analytic on an open interval containing $[\liminf_n\lambda_{\min}^{\boldsymbol\Sigma_n\Theta_n}I_{(0,1)}(y)(1-\sqrt y)^2,\limsup_n\lambda_{\max}^{\boldsymbol\Sigma_n\Theta_n}(1+\sqrt y)^2]$. Under Assumptions A-D, we have that the $\kappa$ dimensional random vector $(L^c(f_j,\mathbf S_n\Theta_n))_{j=1}^\kappa$ is tight and converges weakly to a Gaussian vector $(X_{f_j})_{j=1}^\kappa$. The respective expectation is
\[
\mathrm EX_f=-\frac1{2\pi i}\oint f(z)\left\{
\frac{y\int\frac{\underline m^3(z)t^2}{(\underline m(z)t+1)^3}\,dH(t)}{\left(1-y\int\frac{\underline m^2(z)t^2}{(\underline m(z)t+1)^2}\,dH(t)\right)^2}
+\frac{\underline m^3(z)a(z)}{1-y\int\frac{\underline m^2(z)t^2}{(\underline m(z)t+1)^2}\,dH(t)}\right\}dz,\tag{2.4}
\]
while the covariance is given by
\[
\begin{aligned}
\operatorname{Cov}(X_f,X_g)
={}&-\frac1{2\pi^2}\oint\oint f(z_1)g(z_2)\left(\frac{\frac{d\underline m(z_1)}{dz_1}\frac{d\underline m(z_2)}{dz_2}}{(\underline m(z_2)-\underline m(z_1))^2}-\frac1{(z_1-z_2)^2}\right)dz_1dz_2\\
&-\frac1{4\pi^2}\oint\oint f(z_1)g(z_2)\frac{\partial^2\underline m(z_1)\underline m(z_2)d_2(z_1,z_2)}{\partial z_2\partial z_1}\,dz_1dz_2,\tag{2.5}
\end{aligned}
\]
where $f,g\in\{f_1,\ldots,f_\kappa\}$. The limiting parameters can be expressed as follows by denoting $\mathbb T_n^{(1)}(\Theta_n,\boldsymbol\Sigma_n,\mathbb P_n,z)=\boldsymbol\Theta_n^{1/2}(\underline m(z)\Psi_n+\mathbf I_p)^{-1}\boldsymbol\Theta_n^{1/2}$ and $\mathbb T_n^{(2)}(\Theta_n,\boldsymbol\Sigma_n,\mathbb P_n,z)=\boldsymbol\Theta_n^{1/2}(\underline m(z)\Psi_n+\mathbf I_p)^{-2}\boldsymbol\Theta_n^{1/2}$:
\[
\begin{aligned}
a(z)={}&\lim_{n\to\infty}n^{-1}\mathcal I_2\big(\mathbb T_n^{(1)}(\Theta_n,\boldsymbol\Sigma_n,\mathbb P_n,z),\mathbb T_n^{(2)}(\Theta_n,\boldsymbol\Sigma_n,\mathbb P_n,z),\boldsymbol\Sigma_n,\mathbb P_n\big)\\
&+(\nu_4-3)\lim_{n\to\infty}n^{-1}\mathcal{II}\big(\mathbb T_n^{(1)}(\Theta_n,\boldsymbol\Sigma_n,\mathbb P_n,z),\mathbb T_n^{(2)}(\Theta_n,\boldsymbol\Sigma_n,\mathbb P_n,z),\boldsymbol\Sigma_n,\mathbb P_n\big).
\end{aligned}
\]
\[
\begin{aligned}
d_2(z_1,z_2)={}&\lim_{n\to\infty}n^{-1}\mathcal I_2\big(\mathbb T_n^{(1)}(\Theta_n,\boldsymbol\Sigma_n,\mathbb P_n,z_1),\mathbb T_n^{(1)}(\Theta_n,\boldsymbol\Sigma_n,\mathbb P_n,z_2),\boldsymbol\Sigma_n,\mathbb P_n\big)\\
&+(\nu_4-3)\lim_{n\to\infty}n^{-1}\mathcal{II}\big(\mathbb T_n^{(1)}(\Theta_n,\boldsymbol\Sigma_n,\mathbb P_n,z_1),\mathbb T_n^{(1)}(\Theta_n,\boldsymbol\Sigma_n,\mathbb P_n,z_2),\boldsymbol\Sigma_n,\mathbb P_n\big).
\end{aligned}
\]
Moreover, both in equation (2.4) and (2.5), the contours are closed and taken in the positive direction in the complex plane. Each contour encloses the support of $F^{y,H}$, with the two contours in equation (2.5) assumed to be nonoverlapping.

Fix $\varepsilon>0$ and let $(\mu,\nu)\in\mathcal{P}(\mathbb{R}^{d_{x}})\times\mathcal{P}(\mathbb{R}^{d_{y}})$ be a pair of 4-sub-Weibull distributions with parameter $\sigma^{2}>0$. We have

\[
\begin{aligned}
\mathbb{E}\big[\big|\mathsf{S}_{\varepsilon}(\mu,\nu)-\mathsf{S}_{\varepsilon}(\hat{\mu}_{n},\nu)\big|\big] & \lesssim_{d_{x},d_{y}}\frac{1+\sigma^{4}}{\sqrt{n}}+\varepsilon\Bigg(1+\bigg(\frac{\sigma}{\sqrt{\varepsilon}}\bigg)^{9\left\lceil\frac{d_{x}}{2}\right\rceil+11}\Bigg)\frac{1}{\sqrt{n}} \\ \mathbb{E}\big[\big|\mathsf{S}_{\varepsilon}(\mu,\nu)-\mathsf{S}_{\varepsilon}(\hat{\mu}_{n},\hat{\nu}_{n})\big|\big] & \lesssim_{d_{x},d_{y}}\frac{1+\sigma^{4}}{\sqrt{n}}+\varepsilon\Bigg(1+\bigg(\frac{\sigma}{\sqrt{\varepsilon}}\bigg)^{9\left\lceil\frac{d_{x}\vee d_{y}}{2}\right\rceil+11}\Bigg)\frac{1}{\sqrt{n}}.
\end{aligned}
\]

Let $(\mu,\nu)\in\mathcal{P}(\mathcal{X})\times\mathcal{P}(\mathcal{Y})$, where $\mathcal{X}\subset\mathbb{R}^{d_{x}}$ and $\mathcal{Y}\subset\mathbb{R}^{d_{y}}$ are compact, and let $R=\mathrm{diam}(\mathcal{X})\vee\mathrm{diam}(\mathcal{Y})$. We have

\[
\begin{aligned}
\mathbb{E}\big[\big|\mathsf{D}(\mu,\nu)^{2}-\mathsf{D}(\hat{\mu}_{n},\nu)^{2}\big|\big] & \lesssim_{d_{x},d_{y}}\frac{R^{4}}{\sqrt{n}}+\big(1+R^{4}\big)n^{-\frac{2}{d_{x}\vee 4}}(\log n)^{\mathds{1}_{\{d_{x}=4\}}} \\ \mathbb{E}\big[\big|\mathsf{D}(\mu,\nu)^{2}-\mathsf{D}(\hat{\mu}_{n},\hat{\nu}_{n})^{2}\big|\big] & \lesssim_{d_{x},d_{y}}\frac{R^{4}}{\sqrt{n}}+\big(1+R^{4}\big)n^{-\frac{2}{(d_{x}\wedge d_{y})\vee 4}}(\log n)^{\mathds{1}_{\{d_{x}\wedge d_{y}=4\}}},
\end{aligned}
\]

and if $\mu,\nu$ are separated in the $(2,2)$-GW distance, i.e., $\mathsf{D}(\mu,\nu)>0$, then the same rates hold for estimating $\mathsf{D}$ itself, without the square.

Furthermore, the above rates are sharp in the sense that for any $n$ large enough, we have

\[
\begin{aligned}
\sup_{(\mu,\nu)\in\mathcal{P}(\mathcal{X})\times\mathcal{P}(\mathcal{Y})}\mathbb{E}\big[\big|\mathsf{D}(\mu,\nu)^{2}-\mathsf{D}(\hat{\mu}_{n},\nu)^{2}\big|\big] & \gtrsim_{\,d_{x},d_{y},R}\,n^{-\frac{2}{d_{x}\vee 4}} \\ \sup_{(\mu,\nu)\in\mathcal{P}(\mathcal{X})\times\mathcal{P}(\mathcal{Y})}\mathbb{E}\big[\big|\mathsf{D}(\mu,\nu)^{2}-\mathsf{D}(\hat{\mu}_{n},\hat{\nu}_{n})^{2}\big|\big] & \gtrsim_{\,d_{x},d_{y},R}\,n^{-\frac{2}{(d_{x}\wedge d_{y})\vee 4}}.
\end{aligned}
\]

Assume Condition 1 holds and $v_2\asymp1$. Let $\beta^*,d^*$ and $\gamma^*$ be as in (2.6), and $N,L\geq3$ satisfying $(NL)\asymp\{n/\log^6(n)\}^{\nu^\dagger/(4\gamma^*+2\nu^\dagger)}$ for $\nu^\dagger=1-1/p$. Consider the approximate least squares estimates with optimization error bounded by $\delta_{n,\mathrm{LS}}^2$, where $\delta_{n,\mathrm{LS}}\asymp\{\log^6(n)/n\}^{\gamma^*\nu^\dagger/(2\gamma^*+\nu^\dagger)}v_p^{1/(2p)}$ and the depth and width of the network class $\mathcal F_n=\mathcal F_n(d,\bar L,\bar N,M)$ satisfy (3.15). Then, for all sufficiently large $n$, the following bound
\[
\sup_{\substack{f_0\in\mathcal H(d,l,\mathcal P)\\\mathbb E[\varepsilon\mid X]=0,\mathbb E[|\varepsilon|^p\mid X]\leq v_p}}
\mathbb P\left\{\sup_{f\in\mathcal S_{n,\infty}(\delta_{n,\mathrm{LS}})}\|f-f_0\|_2\geq c_7D\delta_{n,\mathrm{LS}}\right\}\leq c_7D^{-2p}
\]
holds for any $D\geq1$, where $c_7$ is a universal constant independent of $(n,D,p,v_p)$.

Suppose that we are testing $\mathcal P=\{P_1,\ldots,P_L\}$ against $\mathcal Q=\{Q\}$ and (JA) holds. The following are equivalent:
(a) there exists an exact (hence pivotal) and nontrivial p-variable;
(b) there exists a pivotal, exact, bounded e-variable that has nontrivial e-power against $Q$;
(c) there exists an exact e-variable that is nontrivial against $Q$;
(d) there exists a random variable $X$ that is pivotal for $\mathcal P$ but has a different distribution under $Q$, where the laws of $X$ under both are atomless;
(e) it holds that $Q\notin\operatorname{Span}(P_1,\ldots,P_L)$.

Suppose that we are testing $\mathcal P=\{P_1,\ldots,P_L\}$ against $\mathcal Q=\{Q\}$ and (JA) holds. The following are equivalent:
(a) there exists a nontrivial p-variable;
(b) there exists a bounded e-variable that has nontrivial e-power against $Q$;
(c) there exists an e-variable that is nontrivial for $Q$;
(d) it holds that $Q\notin\operatorname{Conv}(P_1,\ldots,P_L)$.

Assume (JA). Suppose that we are testing $\mathcal P=\{P_1,\ldots,P_L\}$ against $\mathcal Q=\{Q_1,\ldots,Q_M\}$. The following are equivalent:
(a) there exists an exact (hence pivotal) and nontrivial p-variable;
(b) there exists a pivotal, exact, bounded e-variable that has nontrivial e-power against $\mathcal Q$;
(c) there exists an exact e-variable that is nontrivial for $\mathcal Q$;
(d) there exists a random variable $X$ that is pivotal for $\mathcal P$ and satisfies $F\notin\operatorname{Conv}(G_1,\ldots,G_M)$, where $F$ is the law of $X$ under every $P\in\mathcal P$ and $G_j$ is the law of $X$ under $Q_j$ for $1\le j\le M$;
(e) it holds that $\operatorname{Span}(P_1,\ldots,P_L)\cap\operatorname{Conv}(Q_1,\ldots,Q_M)=\varnothing$.
Furthermore, the equivalence of (c) and (e) does not require (JA).

